<script setup lang="ts">
import { computed,ref } from 'vue';
import type { Study } from './model.ts';
const props=defineProps<{study:Study}>(),index=ref(0),expanded=ref(false);
const conflict=computed(()=>props.study.roadConflicts?.[index.value]);
const building=computed(()=>props.study.buildings.find(b=>b.id===conflict.value?.buildingId));
const road=computed(()=>props.study.roads.find(r=>r.id===conflict.value?.roadId));
const view=computed(()=>{const p=building.value?.points??[];const x=p.reduce((s,p)=>s+p.x,0)/p.length,z=p.reduce((s,p)=>s+p.z,0)/p.length;return `${x-35} ${z-35} 70 70`;});
const pieces=computed(()=>props.study.roadSurface?.filter(p=>p.roadId===road.value?.id)??[]);
</script>
<template><section v-if="conflict&&building&&road" class="conflict-review" :class="{expanded}"><h3>Road / building review</h3><button @click="expanded=!expanded">{{ expanded?'Close conflict review':'Expand conflict review' }}</button><select aria-label="Review road conflict" v-model.number="index"><option v-for="(c,i) in study.roadConflicts" :key="i" :value="i">{{ c.kind }} · way {{ c.roadId }} / {{ c.buildingId }}</option></select><p>Road {{ road.id }} / building {{ building.id }}. {{ conflict.decision }} Exact original records are retained.</p><div class="conflict-views"><figure v-for="mode in ['Before','After']" :key="mode"><figcaption>{{ mode }} · {{ mode==='Before'?'assumed 5 m road':'clearance-corrected surface' }}</figcaption><svg :viewBox="view" role="img" :aria-label="mode+' road building overlap'"><polyline v-if="mode==='Before'" :points="road.points.map(p=>`${p.x},${p.z}`).join(' ')" stroke="#708982" stroke-width="5" fill="none" stroke-linecap="round" stroke-linejoin="round"/><template v-else><line v-for="(p,i) in pieces" :key="i" :x1="p.a.x" :y1="p.a.z" :x2="p.b.x" :y2="p.b.z" :stroke-width="p.halfWidth*2" stroke="#708982" stroke-linecap="round"/></template><polygon :points="building.points.map(p=>`${p.x},${p.z}`).join(' ')" fill="#c89573aa" stroke="#9a533b" stroke-width=".3"/><polyline :points="road.points.map(p=>`${p.x},${p.z}`).join(' ')" stroke="#d66730" stroke-width=".3" stroke-dasharray="1 1" fill="none"/></svg></figure></div><p>Orange dashed line: unchanged OSM centerline, shown for review even where the game suppresses a conflicting surface. Building shape and position are unchanged.</p></section></template>
<style scoped>.conflict-review select{width:100%;font-size:10px;min-height:44px}.conflict-review button{min-height:44px;border:1px solid #a1b49a;border-radius:6px;background:#e4eadb;margin:8px 0;padding:8px}.conflict-review p{font-size:10px;line-height:1.5}.conflict-views{display:grid;grid-template-columns:1fr 1fr;gap:8px}.conflict-views figure{margin:0}.conflict-views svg{width:100%;height:170px;background:#ece4d2;border:1px solid #c6bca6}.conflict-views figcaption{font-size:9px;margin:8px 0}.expanded{position:absolute;inset:10px;z-index:9;background:#faf8ed;padding:24px;overflow:auto;border-radius:12px;box-shadow:0 0 40px #23453744}.expanded .conflict-views svg{height:50vh}.expanded .conflict-views figcaption,.expanded p{font-size:12px}@media(max-width:700px){.expanded{padding:12px}.expanded .conflict-views{grid-template-columns:1fr}.expanded .conflict-views svg{height:240px}}</style>
